function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  let moonSize = 100;
  let moonX = W / 2;
  let moonY = H / 2;
  let phase = Math.sin(t);
  if (phase < 0) {
    phase = -phase;
    ctx.beginPath();
    ctx.arc(moonX, moonY, moonSize, Math.PI / 2, Math.PI * (1.5 + phase));
    ctx.lineTo(moonX, moonY);
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.arc(moonX, moonY, moonSize, Math.PI / 2 - phase * Math.PI, Math.PI * (1.5 + phase));
    ctx.lineTo(moonX, moonY);
    ctx.fill();
  }
  ctx.beginPath();
  ctx.arc(moonX, moonY, moonSize, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}
